      Z(4)=x*Z(4)
      Z(3)=8*Z(4) + Z(3)
      Z(3)=t*Z(3)
      Z(2)=2*Z(3) + Z(2)

      W(6) = iPq*Z(2)

END SUBROUTINE dlg_d_intB_V1Acpi_DD_ch
